VALUES (2, 9, 2, 'INSTRUÇÃO NORMATIVA Nº 1, DE 27 DE MAIO DE 2020; Decreto nº 12.572/2025', 'Normative Instruction No. 1 of May 27, 2020; Decree No. 12.572/2025', 'Elaboração da Política de Segurança da Informação', 'Development of the Information Security Policy', 'Conhecimento para elaborar, coordenar, implementar e promover a divulgação da política de segurança da informação do órgão ou entidade, suas normas de apoio, metodologias e procedimentos conforme normas do GSI/PR', 'Knowledge required to draft, coordinate, implement, and publicize the information security policy of the agency or entity, its supporting standards, methodologies, and procedures, according to GSI/PR regulations.');

-- GSI-011 | Gestão de Segurança da Informação | Básico
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (2, 9, 2, 'NC 17, 18; ENISA - European Cybersecurity Skills Framework (ECSF)', 'Complementary Standards 17 and 18; ENISA - European Cybersecurity Skills Framework (ECSF)', 'Ensino e promoção da cultura de segurança da informação', 'Education and Promotion of an Information Security Culture', 'Conhecimento das diretrizes para planejar, executar e avaliar ações de sensibilização, conscientização, capacitação e especialização em segurança da informação nos órgãos e entidades da Administração Pública Federal, adequando conteúdos aos públicos e incorporando atividades práticas e colaboração entre equipes.', 'Knowledge of guidelines for planning, delivering, and evaluating awareness-raising, education, training, and specialization activities in information security within federal public administration agencies and entities, tailoring content to target audiences and incorporating practical activities and collaboration across teams.');

-- GSI-012 | Gestão de Segurança da Informação | Básico
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (2, 9, 2, 'PORTARIA SGD/MGI Nº 852', 'SGD/MGI Ordinance No. 852', 'Centro de Excelência em Privacidade e Segurança da Informação do Governo Digital', 'Digital Government Center of Excellence in Privacy and Information Security', 'Conhecimento das ações realizadas pelo Centro de Excelência em Privacidade e Segurança da Informação do Governo Digital, que tem como missão promover a cultura de privacidade e segurança da informação nos órgãos e entidades', 'Knowledge of the initiatives undertaken by the Digital Government Center of Excellence in Privacy and Information Security, whose mission is to promote a culture of privacy and information security in government agencies and entities.');

-- GSI-013 | Gestão de Segurança da Informação | Básico
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (2, 9, 2, 'Competency Models for Information Security and Cybersecurity Professionals; Competencies of Information Technology Professionals in Society 5.0', 'Competency Models for Information Security and Cybersecurity Professionals; Competencies of Information Technology Professionals in Society 5.0', 'Ética, responsabilidade e sigilo profissional em segurança da informação', 'Ethics, Responsibility, and Professional Confidentiality in Information Security', 'Capacidade de atuar com integridade, responsabilidade, discrição e respeito aos deveres legais e organizacionais, preservando o sigilo de informações sensíveis, prevenindo usos indevidos de privilégios e avaliando as consequências éticas de decisões e ações de segurança.', 'Ability to act with integrity, responsibility, discretion, and respect for legal and organizational duties, preserve the confidentiality of sensitive information, prevent misuse of privileges, and assess the ethical consequences of security decisions and actions.');

