-- SBD-001 | Security by Design | Intermediário
INSERT INTO public.tb_competencias(fk_dominio_conhecimento, fk_area_conhecimento, fk_dificuldade, no_origem_competencias_pt, no_origem_competencias_en, no_competencias_pt, no_competencias_en, ds_competencias_pt, ds_competencias_en)
VALUES (2, 17, 3, 'NIST SP 800-218 (SSDF); Novel Approach for Cybersecurity Workforce Development: A Course in Secure Design', 'NIST SP 800-218 (SSDF); Novel Approach for Cybersecurity Workforce Development: A Course in Secure Design', 'Conceitos Fundamentais de Security by Design', 'Fundamental Concepts of Security by Design', 'Conhecimento sobre Security By Design, visando que a segurança não deve ser adicionada ao final de um projeto, mas incorporada desde a fase de concepção, prevenindo vulnerabilidades estruturais em sistemas, aplicações e processos.', 'Knowledge of Security by Design, whereby security must not be added at the end of a project but incorporated from the design stage onward, preventing structural vulnerabilities in systems, applications, and processes.');

